  cacheComponents: true,
  partialPrefetching: true,
}

export default nextConfig

async get(cacheKey: string, softTags: string[]) {
  const entry = await redis.get(cacheKey)
  if (!entry) {
    throw new Error('cache miss')
  }
  return JSON.parse(entry)
}
